REVOKE UPDATE ON public.profiles FROM authenticated; GRANT UPDATE(full_name,phone,country) ON public.profiles TO authenticated; REVOKE UPDATE ON public.notifications FROM authenticated; GRANT UPDATE(read_at) ON public.notifications TO authenticated; CREATE OR REPLACE FUNCTION public.submit_kyc() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; UPDATE public.profiles SET kyc_status='pending' WHERE id=auth.uid() AND kyc_status IN ('not_started','rejected'); IF NOT FOUND THEN RAISE EXCEPTION 'Verification already submitted'; END IF; INSERT INTO public.activity_logs(user_id,action) VALUES(auth.uid(),'kyc_submitted'); END $$; CREATE OR REPLACE FUNCTION public.review_kyc(_user_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff(auth.uid()) OR _status NOT IN ('verified','rejected') THEN RAISE EXCEPTION 'Not allowed'; END IF; UPDATE public.profiles SET kyc_status=_status WHERE id=_user_id AND kyc_status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Submission unavailable'; END IF; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id) VALUES(auth.uid(),'kyc_'||_status,'profile',_user_id); INSERT INTO public.notifications(user_id,title,message) VALUES(_user_id,'Verification '||_status,'Your identity review is complete.'); END $$; REVOKE ALL ON FUNCTION public.submit_kyc(),public.review_kyc(uuid,text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.submit_kyc(),public.review_kyc(uuid,text) TO authenticated;